function animate(env,el,p) {
    let t = env.time;
    var xposition = p.posx;
    if ( p.xinv ) {
    xposition = xposition * -1;
    }
    var zposition = p.posz;
    if ( p.zinv ) {
    zposition = 1.0 + (1.0 - zposition);
    }
    var yposition = p.posy;
    if ( p.yinv ) {
    yposition = yposition * -1;
    }
    var aposition = p.angle;
    if ( p.ainv ) {
    aposition = aposition * -1;
    }
    el.transform.location.x += xposition;
    el.transform.location.y += yposition;
    el.transform.angle += aposition;
    el.transform.scale.x += zposition-1;
    el.transform.scale.y += zposition-1;
    return el;
}
